namespace e193 {
using namespace e191;
using Features=std::array<double,12>;
Features features(const float*q,size_t d,const float*p,const float*D,size_t K){
 std::array<double,3> z{p[0],p[1],p[2]};std::sort(z.begin(),z.end());double norm=0;for(size_t j=0;j<d;++j)norm+=double(q[j])*q[j];double gap=double(D[K-1])-D[0];
 return {z[0],z[1]-z[0],z[2]-z[0],norm,(z[2]-z[0])/(1+std::abs(z[0])),D[0],D[K/4],D[K/2],D[3*K/4],D[K-1],gap,gap/(1+std::abs(double(D[0])))};
}
struct Node{int f,left,right;double threshold,gain,cost;};
struct Gate{
 std::string kind="off";size_t nf=0;double threshold=0;std::vector<double>mean,scale,wg,wc;std::vector<Node>nodes;
 Gate(){} explicit Gate(const fs::path&p){auto j=read_json(p);kind=j.at("kind");threshold=j.value("threshold",0.);nf=j.value("nf",size_t(0));if(kind=="ridge"){mean=j.at("mean").get<std::vector<double>>();scale=j.at("scale").get<std::vector<double>>();wg=j.at("wg").get<std::vector<double>>();wc=j.at("wc").get<std::vector<double>>();}else if(kind=="tree")for(auto n:j.at("nodes"))nodes.push_back({n.at("f"),n.at("left"),n.at("right"),n.at("threshold"),n.at("gain"),n.at("cost")});}
 bool on(const float*q,size_t d,const float*p,const float*D,size_t K)const{if(kind=="off")return false;if(kind=="on")return true;auto x=features(q,d,p,D,K);double g=0,c=0;if(kind=="ridge"){g=wg[nf];c=wc[nf];for(size_t j=0;j<nf;++j){double z=(x[j]-mean[j])/scale[j];g+=wg[j]*z;c+=wc[j]*z;}}else{int a=0;while(nodes[a].f>=0){const auto&n=nodes[a];a=x[n.f]<=n.threshold?n.left:n.right;}g=nodes[a].gain;c=nodes[a].cost;}return std::max(g,0.)/std::max(c,1.)>=threshold;}
};
struct Meter{Stats st;std::vector<uint8_t> enabled;};
void gated(acsg::IndexACSGFlat&idx,const std::vector<float>&q,int L,const std::string&m,Router&r,Posting&p,Backend&e,const Gate&g,const std::vector<uint8_t>&oracle,Batch&b,Meter&mt){
 mt.enabled.assign(b.n,0);if(m=="GT10"||m=="B32"||m=="REUSE-SQ"){e191::run(idx,q,L,m,r,p,e,b,mt.st);if(m!="GT10")std::fill(mt.enabled.begin(),mt.enabled.end(),1);return;}
 idx.acsg.search_L=L;std::vector<std::vector<acsg::EnterPoint>>eps(b.n);for(size_t i=0;i<b.n;++i){auto v=r.route(q.data()+i*idx.d);for(int j=0;j<3;++j){b.entries[3*i+j]=v.ids[j];b.profile_distances[3*i+j]=v.distances[j];eps[i].emplace_back(v.ids[j],1.f);}}
 faiss::VisitedTable vt(idx.ntotal);std::unique_ptr<faiss::DistanceComputer>dc(acsg::storage_distance_computer(idx.storage));std::vector<acsg::Neighbor>ret;std::vector<faiss::idx_t>ids(b.k);std::vector<int32_t>cur(b.k);mt.st.per_query.reserve(b.n*5);
 for(size_t i=0;i<b.n;++i){auto*qi=q.data()+i*idx.d;dc->set_query(qi);vt.advance();idx.acsg.search_new(*dc,b.k,ids.data(),b.distances.data()+i*b.k,vt,2,eps[i],&ret);for(size_t j=0;j<b.k;++j)cur[j]=ids[j];bool on=m=="GATE-ORACLE"?oracle.at(i):(m=="GATE-LEARNED"&&g.on(qi,idx.d,b.profile_distances.data()+3*i,b.distances.data()+i*b.k,b.k));mt.enabled[i]=on;std::array<uint64_t,5>a{mt.st.scans,mt.st.blocks,mt.st.exact,mt.st.pq,mt.st.sq};if(on)e.complete(*dc,qi,cur.data(),b.distances.data()+i*b.k,b.k,b.entries.data()+3*i,"REUSE-SQ",mt.st);std::copy(cur.begin(),cur.end(),b.ids.begin()+i*b.k);std::array<uint64_t,5>z{mt.st.scans,mt.st.blocks,mt.st.exact,mt.st.pq,mt.st.sq};for(size_t j=0;j<5;++j)mt.st.per_query.push_back(z[j]-a[j]);}
}
__attribute__((noinline)) double timegate(acsg::IndexACSGFlat&idx,const std::vector<float>&q,int L,const std::string&m,Router&r,Posting&p,Backend&e,const Gate&g,const std::vector<uint8_t>&oracle,Batch&dest,Meter&mt){auto t=Clock::now();{Batch b(dest.n,dest.k);gated(idx,q,L,m,r,p,e,g,oracle,b,mt);copy_packet(b,dest);asm volatile(""::"g"(dest.ids.data()),"g"(b.ids.data()):"memory");}return seconds(t);}
void check_selection(const Batch&main,const Batch&sq,const Batch&b,const std::vector<uint8_t>&v){require(v.size()==b.n&&b.entries==main.entries&&b.profile_distances==main.profile_distances,"gate route equality");for(size_t i=0;i<b.n;++i){const auto&s=v[i]?sq:main;for(size_t j=0;j<b.k;++j)require(b.ids[i*b.k+j]==s.ids[i*b.k+j]&&equal_float(b.distances[i*b.k+j],s.distances[i*b.k+j]),"gate actual query selection equality");}}
json bench(const json&c,const std::string&mode){check_threads(c);auto start=Clock::now();fs::path root=c.at("output_dir");fresh_dir(root);fresh_json(root/"config.json",c);json binding;auto idx=load_index(c,binding);Matrix qm(c.at("queries"));auto q=qm.copy();Router r(c.at("router"),idx->d,idx->ntotal);Posting p(c.at("table"),idx->ntotal);Backend e(c);json results=json::array();size_t batches=0,ordinal=0;int reps=mode=="formal"?3:1;
 fresh_json(root/"environment.json",{{"threads",process_threads()},{"cpu",15},{"binding",binding},{"startup_seconds",seconds(start)},{"timer","Batch lifecycle, route/main, features/predict/branch, conditional completion, six-array copy/destruction"}});
 for(auto kj:c.at("Ks")){size_t K=kj;Gate g;std::vector<uint8_t>oracle(qm.n,0);if(mode!="labels"){g=Gate(c.at("gate_models").at(std::to_string(K)).get<std::string>());oracle=read_raw<uint8_t>(c.at("oracle_masks").at(std::to_string(K)).get<std::string>());require(oracle.size()>=qm.n,"mask n");}
 std::vector<int> ls=mode=="formal"?c.at("GT_L").get<std::vector<int>>():std::vector<int>{200};
 for(int L:ls){require(L>=int(K),"true K budget");std::vector<std::string> methods={"GT10"};if(L==200)methods=mode=="labels"?std::vector<std::string>{"GT10","REUSE-SQ"}:std::vector<std::string>{"GT10","B32","REUSE-SQ","GATE-OFF","GATE-ORACLE","GATE-LEARNED"};size_t M=methods.size();std::vector<std::unique_ptr<Batch>>first(M);std::vector<Meter> meters(M);std::vector<json>rounds(M,json::array());
 for(int rep=0;rep<reps;++rep)for(size_t off=0;off<M;++off){size_t mi=(ordinal+rep+off)%M;auto m=methods[mi];check_threads(c);if(rep==0){Batch warm(std::min<size_t>(256,qm.n),K);Meter z;gated(*idx,q,L,m,r,p,e,g,oracle,warm,z);}Batch dest(qm.n,K);Meter mt;double wall=timegate(*idx,q,L,m,r,p,e,g,oracle,dest,mt);++batches;check_threads(c);validate(dest,idx->ntotal);fs::path out=root/("k"+std::to_string(K))/(m+"_L"+std::to_string(L));auto digest=packet_sha(dest);if(rep==0){first[mi]=std::make_unique<Batch>(dest);meters[mi]=mt;dest.save(out/"raw",false);write_raw(out/"enabled.u8",mt.enabled);if(!mt.st.per_query.empty())write_raw(out/"access.u64",mt.st.per_query);}else {all_same(*first[mi],dest);require(mt.enabled==meters[mi].enabled,"gate deterministic");}json v={{"round",rep},{"wall_seconds",wall},{"qps",qm.n/wall},{"packet_sha256",digest},{"threads",process_threads()},{"enabled_queries",std::accumulate(mt.enabled.begin(),mt.enabled.end(),uint64_t(0))},{"scans",mt.st.scans},{"exact",mt.st.exact},{"sq",mt.st.sq}};rounds[mi].push_back(v);fresh_json(out/("round"+std::to_string(rep)+".json"),v);std::cout<<json({{"K",K},{"L",L},{"method",m},{"round",rep},{"qps",qm.n/wall}}).dump()<<std::endl;}
 if(L==200){size_t sqi=mode=="labels"?1:2;auto&main=*first[0];auto&sq=*first[sqi];std::unique_ptr<faiss::DistanceComputer>dc(acsg::storage_distance_computer(idx->storage));for(size_t i=0;i<qm.n;++i){std::vector<int32_t>rr(main.ids.begin()+i*K,main.ids.begin()+(i+1)*K);std::vector<float>dd(main.distances.begin()+i*K,main.distances.begin()+(i+1)*K);dc->set_query(q.data()+i*idx->d);Stats st;e.complete(*dc,q.data()+i*idx->d,rr.data(),dd.data(),K,main.entries.data()+3*i,"REUSE-SQ",st,true);for(size_t j=0;j<K;++j)require(rr[j]==sq.ids[i*K+j]&&equal_float(dd[j],sq.distances[i*K+j]),"SQ full-sort oracle");}
 if(mode!="labels"){audit_merge(*idx,q,main,*first[1],p);for(size_t mi=3;mi<M;++mi)check_selection(main,sq,*first[mi],meters[mi].enabled);}
 else {std::vector<double>x,us(qm.n*3);x.reserve(qm.n*12);for(size_t i=0;i<qm.n;++i){auto f=features(q.data()+i*idx->d,idx->d,main.profile_distances.data()+3*i,main.distances.data()+i*K,K);x.insert(x.end(),f.begin(),f.end());}write_raw(root/("k"+std::to_string(K))/"features.f64",x);
 for(size_t rep=0;rep<3;++rep)for(size_t i=0;i<qm.n;++i){std::vector<int32_t>rr(main.ids.begin()+i*K,main.ids.begin()+(i+1)*K);std::vector<float>dd(main.distances.begin()+i*K,main.distances.begin()+(i+1)*K);dc->set_query(q.data()+i*idx->d);Stats st;auto t=Clock::now();e.complete(*dc,q.data()+i*idx->d,rr.data(),dd.data(),K,main.entries.data()+3*i,"REUSE-SQ",st);us[rep*qm.n+i]=seconds(t)*1e6;for(size_t j=0;j<K;++j)require(rr[j]==sq.ids[i*K+j]&&equal_float(dd[j],sq.distances[i*K+j]),"cost replay equals actual SQ");}write_raw(root/("k"+std::to_string(K))/"completion_cost_us.f64",us);}
 }
 for(size_t mi=0;mi<M;++mi){std::vector<double>w;for(auto v:rounds[mi])w.push_back(v.at("wall_seconds"));std::sort(w.begin(),w.end());auto&mt=meters[mi];json v={{"dataset",c.at("dataset")},{"K",K},{"L",L},{"method",methods[mi]},{"n",qm.n},{"qps",qm.n/w[w.size()/2]},{"rounds",rounds[mi]},{"enabled_queries",std::accumulate(mt.enabled.begin(),mt.enabled.end(),uint64_t(0))},{"scans_per_query",double(mt.st.scans)/qm.n},{"exact_per_query",double(mt.st.exact)/qm.n},{"all_round_bits_equal",true},{"result_dir",(root/("k"+std::to_string(K))/(methods[mi]+"_L"+std::to_string(L))).string()}};fresh_json(fs::path(v.at("result_dir"))/"result.json",v);results.push_back(v);}++ordinal;
 }}json done={{"status","PASS_E193_"+mode},{"points",results.size()},{"batches",batches},{"results",results},{"GT_read_by_search",false},{"outer_seconds",seconds(start)}};fresh_json(root/"complete.json",done);return done;}
}
